'use strict';

class Response {
    constructor(raw, httpStatus) {
        this._raw = raw;
        this._httpStatus = httpStatus;
    }

    ok() {
        return this._raw.status ?? false;
    }
    message() {
        return this._raw.message ?? '';
    }
    data() {
        return this._raw.data ?? null;
    }
    code() {
        return this._raw.metadata?.code ?? '';
    }
    traceId() {
        return this._raw.metadata?.trace_id ?? '';
    }
    httpStatus() {
        return this._httpStatus;
    }
    toObject() {
        return this._raw;
    }

    successful() {
        return this.code() === 'TRANSACTION_SUCCESSFUL';
    }
    processing() {
        return this.code() === 'ERR_TRANSACTION_PROCESSING';
    }
    failed() {
        return this.code() === 'ERR_TRANSACTION_FAILED';
    }
}

module.exports = {
    Response
};